  function paint(){content.replaceChildren();const ready=checkoutCartReady(state.items),invalid=state.items.some(id=>checkoutCartStatus(id).reason);content.append(message(ready?'Every saved item is currently available for kiosk checkout. The kiosk will check availability again.':state.items.length?'Remove blocked or unavailable items before checkout at the kiosk.':'Your saved cart is empty. Add equipment below.','notice'));content.append(panel(node('h2','Saved items'),table(['Equipment','Asset code','Current availability','Action'],state.items.map(id=>{const status=checkoutCartStatus(id),item=status.item;return [item?.name||'Unavailable equipment · '+id,item?.assetId||'',status.reason||'Ready for kiosk checkout',button('Remove',()=>update(state.items.filter(value=>value!==id)))]}))));if(invalid)content.append(button('Remove unavailable or blocked items',()=>update(checkoutCartReadyItems(state.items)),'main'));const matches=equipment.filter(item=>!state.items.includes(item.id)&&[item.name,item.assetId].join(' ').toLowerCase().includes(search.value.toLowerCase()));content.append(panel(node('h2','Add equipment'),table(['Equipment','Asset code','Current availability','Action'],matches.map(item=>{const status=checkoutCartStatus(item.id),add=button('Add',()=>update([...state.items,item.id]));add.disabled=!!status.reason||state.items.length>=50;return [item.name,item.assetId||'',status.reason||'Ready',add]}))))}
